	/** Folder migration can touch disk, so it runs on RuneLite's worker. */
	private synchronized void prepareFolder()
	{
		if (preparingFolder || folder != null) { return; }
		preparingFolder = true;
		notice = "Preparing the recording folder…";
		executor.execute(() ->
		{
			try
			{
				folder = getPluginDirectory();
				notice = "Ready to record.";
			}
			catch (java.io.IOException | RuntimeException e)
			{
				notice = "Could not prepare the recording folder: " + rootMessage(e)
					+ "\nPress Start recording to retry.";
			}
			finally { preparingFolder = false; }
		});
	}

	String folderPath()
	{
		return folder == null ? "The recording folder is not ready yet." : folder.toString();
	}

	boolean canRecover()
	{
		OsrsCapture pending = pendingSave;
		return pending != null && pending.recorder().state() == Recorder.State.FAILED;
	}

	void retrySave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				handingOff = true;
				watchSave(pendingSave, pendingSave.recorder().finish());
			}
		});
	}

	void discardSave()
	{
		clientThread.invoke(() ->
		{
			if (canRecover())
			{
				((MccrFileRecorder) pendingSave.recorder()).discard();
				pendingSave = null;
				save = CompletableFuture.completedFuture(null);
				notice = "Unsaved recording discarded.";
			}
		});
	}

	void startRecording()
	{
		stopped = false;
		manual = true;
		if (folder == null) { prepareFolder(); }
		clientThread.invoke(() ->
		{
			if (capture == null && client.getGameState() == GameState.LOGGED_IN)
			{
				beginCapture(true);
			}
		});
	}

	void stopRecording()
	{
		stopped = true;
		manual = false;
		continuing = false;
		clientThread.invoke(() -> endCapture("stopped by you", false, true));
	}

	PanelState panelState()
	{
		OsrsCapture current = capture;
		List<SavedFile> files = new ArrayList<>(saved);
		StringBuilder text = new StringBuilder();
		if (current == null)
		{
			OsrsCapture pending = pendingSave;
			boolean recover = pending != null && pending.recorder().state() == Recorder.State.FAILED;
			boolean resume = enabled && !stopped && (manual || continuing || config.recordOnLogin());
			text.append(handingOff ? "Saving your recording." + (resume ? " Recording resumes after it is saved." : "")
				: recover ? "Recording paused. The unsaved part is kept as a .partial file.\n\n"
					+ pending.recorder().error() + "\n\nRetry saving, or discard it."
				: stopped ? "Not recording." : notice);
			boolean in = loggedIn;
			if (!in)
			{
				text.append("\n\nLog in to start recording.");
			}
			else if (stopped && pending == null)
			{
				text.append("\n\nWhat you played so far is kept. Press Start recording to begin a new one.");
			}
			return new PanelState(text.toString(), "", files, handingOff && resume,
				in && !recover && (pending == null || handingOff));
		}
		text.append(current.status());
		Recorder recorder = current.recorder();
		if (recorder.state() == Recorder.State.FAILED)
		{
			text.append("\n\nCannot save: ").append(recorder.error());
		}
		else
		{
			text.append("\n\nOther players are recorded as unnamed figures.");
		}
		boolean busy = !current.recording();
		String name = recorder instanceof MccrFileRecorder && ((MccrFileRecorder) recorder).path() != null
			? ((MccrFileRecorder) recorder).path().getFileName().toString()
			: "";
		return new PanelState(text.toString(), name, files, !busy, !busy);
	}

	private boolean wantsRecording()
	{
		return enabled && !stopped && (manual || continuing || config.recordOnLogin())
			&& client.getGameState() == GameState.LOGGED_IN;
	}

	static String fileStem(String playerName)
	{
		String who = playerName == null ? "" : playerName.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "-").replaceAll("^-|-$", "");
		String when = java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("yyyyMMdd-HHmm"));
		return "osrs-" + when + (who.isEmpty() ? "" : "-" + who);
	}

	private void changeScene()
	{
		WorldView view = client.getTopLevelWorldView();
		sceneIdentity = SceneIdentity.of(view);
		OsrsCapture current = capture;
		if (current != null) { current.sceneChanged(view); }
		rediscover = true;
	}

	private void beginCapture(boolean freshBaseline)
	{
		if (!wantsRecording() || capture != null || pendingSave != null || handingOff || folder == null)
		{
			return;
		}
		Player me = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (view == null || me == null) { return; }
		sceneIdentity = SceneIdentity.of(view);
		String dimension = sceneIdentity.dimension();
		if (series == null)
		{
			series = java.util.UUID.randomUUID().toString();
			nextPart = 1;
			pseudonyms.clear();
		}
		// Resolve the filename on the first scene tick, when the character name is available.
		Recorder recorder = new MccrFileRecorder(gson, folder, () ->
		{
			Player who = client.getLocalPlayer();
			return fileStem(who == null ? null : who.getName());
		}, executor);
		OsrsCapture next = new OsrsCapture(client, recorder, config, dimension, me == null ? null : me.getName(), client.getWorld(),
			series, nextPart++, pseudonyms, config.chunkMinutes() * 60.0);
		next.account(accountKey());
		capture = next;
		continuing = true;
		rediscover = freshBaseline;
		notice = "Recording.";
		next.start().whenComplete((ignored, throwable) ->
		{
			if (throwable != null)
			{
				notice = "Could not start the recording file: " + rootMessage(throwable);
				log.debug("capture open failed", throwable);
			}
		});
	}

	/** Opaque account key; the salt lives in plugin settings. */
	private String accountKey()
	{
		String salt = configManager.getConfiguration(EmbertideConfig.GROUP, AccountKey.SALT_KEY);
		if (salt == null || salt.isEmpty())
		{
			salt = AccountKey.newSalt();
			configManager.setConfiguration(EmbertideConfig.GROUP, AccountKey.SALT_KEY, salt);
		}
		return AccountKey.of(salt, client.getAccountHash());
	}

	private CompletableFuture<Void> endCapture(String reason, boolean openStudio)
	{
		return endCapture(reason, openStudio, false);
	}

	private CompletableFuture<Void> endCapture(String reason, boolean openStudio, boolean planned)
	{
		OsrsCapture current = capture;
		capture = null;
		if (current == null)
		{
			return save;
		}
		pendingSave = current;
		handingOff = true;
		return watchSave(current, current.finish(reason, openStudio, planned));
	}

	private CompletableFuture<Void> watchSave(OsrsCapture current, CompletableFuture<Void> result)
	{
		// Publication is updated before the returned future completes, including on
		// client shutdown when another client-thread callback cannot be relied on.
		save = result.whenComplete((ignored, throwable) ->
		{
			if (throwable == null)
			{
				if (current.recorder().state() == Recorder.State.COMPLETE) { remember(current, null); }
				pendingSave = null;
				notice = current.recorder().state() == Recorder.State.IDLE
					? "Recording cancelled before the first scene." : "Recording saved.";
			}
			else
			{
				notice = "Recording paused: retry saving or discard the unsaved recording.";
				log.warn("Could not save recording", throwable);
			}
			handingOff = false;
		});
		return save;
	}

	private void remember(OsrsCapture ended, Throwable throwable)
	{
		Recorder recorder = ended.recorder();
		String name = recorder instanceof MccrFileRecorder && ((MccrFileRecorder) recorder).path() != null
			? ((MccrFileRecorder) recorder).path().getFileName().toString()
			: "recording " + ended.part();
		String problem = throwable == null ? "" : rootMessage(throwable);
		if (throwable == null && recorder.state() == Recorder.State.FAILED)
		{
			problem = recorder.error();
		}
		saved.add(new SavedFile(name, ended.part(), ended.seconds(), problem));
	}

	private static String rootMessage(Throwable throwable)
	{
		Throwable cause = throwable;
		while (cause.getCause() != null && cause.getCause() != cause)
		{
			cause = cause.getCause();
		}
		return cause.getMessage() == null ? cause.getClass().getSimpleName() : cause.getMessage();
	}

	private static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(0xE8, 0x86, 0x3A));
		g.fillOval(2, 2, 12, 12);
		g.setColor(new Color(0xFF, 0xE0, 0xAD));
		g.fillOval(6, 5, 4, 4);
		g.dispose();
		return image;
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonObject;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;
import net.runelite.client.util.Text;

/** Allowlisted server game messages, kept only as kind and fields. */
final class GameMessages
{
	static final class Match
	{
		final String kind;
		final JsonObject fields;

		Match(String kind, JsonObject fields)
		{
			this.kind = kind;
			this.fields = fields;
		}
	}

	private static final int MAX_NAME = 64;

	private static final Pattern KILL_COUNT = Pattern.compile(
		"Your (?!.* lap count is: )(?:completion count for |subdued |completed )?((?:[A-Z]|herbiboar).*?) (?:(?:kill|harvest|completion|chest|success) )?count is: ([\\d,]+)\\.?");
	private static final Pattern PERSONAL_BEST = Pattern.compile(
		"(?:.*\\s)?(?:[Dd]uration|[Tt]ime): ([\\d:.]+) \\(new personal best\\)\\.?(?:\\s.*)?");
	private static final Pattern PET_FOLLOWER = Pattern.compile("You have a funny feeling like you're being followed\\.?");
	private static final Pattern PET_BACKPACK = Pattern.compile("You feel something weird sneaking into your backpack\\.?");
	private static final Pattern PET_DUPLICATE = Pattern.compile("You have a funny feeling like you would have been followed\\.*");
	private static final Pattern COLLECTION_LOG = Pattern.compile("New item added to your collection log: (.+?)\\.?");
	private static final Pattern VALUABLE_DROP = Pattern.compile("Valuable drop: (?:([\\d,]+) x )?(.+?) \\(([\\d,]+) coins\\)\\.?");
	private static final Pattern UNTRADEABLE_DROP = Pattern.compile("Untradeable drop: (?:([\\d,]+) x )?(.+?)\\.?");
	private static final Pattern CLUE_COMPLETE = Pattern.compile(
		"You have completed ([\\d,]+) (beginner|easy|medium|hard|elite|master) Treasure Trails?\\.?");
	private static final Pattern COMBAT_TASK = Pattern.compile(
		"(?:CA_ID:\\d+\\|)?Congratulations, you've completed an? (easy|medium|hard|elite|master|grandmaster) combat task(?::.*)?\\.?");
	private static final Pattern SLAYER_TASK = Pattern.compile(
		"You've completed ([\\d,]+) (?:(?:Wildy|Wilderness) )?tasks?(?: and received ([\\d,]+) points?)?(?:[,;].*)?\\.?");
	private static final Pattern QUEST_COMPLETE = Pattern.compile("Congratulations, you've completed a quest: (.+?)\\.?");
	private static final Pattern DIARY_COMPLETE = Pattern.compile(
		"Congratulations! You have completed all of the (easy|medium|hard|elite) tasks in the (.+?) area\\..*");
	private static final Pattern SUPERIOR = Pattern.compile("A superior foe has appeared\\.*");
	private static final Pattern OWN_DEATH = Pattern.compile("Oh dear, you are dead!");

	private GameMessages()
	{
	}

	static Match match(ChatMessageType type, String raw)
	{
		if (raw == null || (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM))
		{
			return null;
		}
		String line = Text.removeTags(raw).replace((char) 160, ' ').trim();
		if (line.isEmpty() || line.length() > 300)
		{
			return null;
		}
		Matcher m;
		if ((m = KILL_COUNT.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("boss", name(m.group(1)));
			f.addProperty("count", number(m.group(2)));
			return new Match("kill_count", f);
		}
		if ((m = PERSONAL_BEST.matcher(line)).matches())
		{
			double seconds = duration(m.group(1));
			if (seconds < 0) { return null; }
			JsonObject f = new JsonObject();
			f.addProperty("duration_s", seconds);
			return new Match("personal_best", f);
		}
		if (PET_FOLLOWER.matcher(line).matches()) { return pet("follower"); }
		if (PET_BACKPACK.matcher(line).matches()) { return pet("backpack"); }
		if (PET_DUPLICATE.matcher(line).matches()) { return pet("duplicate"); }
		if ((m = COLLECTION_LOG.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("item", name(m.group(1)));
			return new Match("collection_log", f);
		}
		if ((m = VALUABLE_DROP.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("item", name(m.group(2)));
			f.addProperty("quantity", m.group(1) == null ? 1 : number(m.group(1)));
			f.addProperty("value", number(m.group(3)));
			return new Match("valuable_drop", f);
		}
		if ((m = UNTRADEABLE_DROP.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("item", name(m.group(2)));
			f.addProperty("quantity", m.group(1) == null ? 1 : number(m.group(1)));
			return new Match("untradeable_drop", f);
		}
		if ((m = CLUE_COMPLETE.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("count", number(m.group(1)));
			f.addProperty("tier", m.group(2));
			return new Match("clue_complete", f);
		}
		if ((m = COMBAT_TASK.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("tier", m.group(1));
			return new Match("combat_task", f);
		}
		if ((m = SLAYER_TASK.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("tasks", number(m.group(1)));
			if (m.group(2) != null)
			{
				f.addProperty("points", number(m.group(2)));
			}
			return new Match("slayer_task_complete", f);
		}
		if ((m = QUEST_COMPLETE.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("quest", name(m.group(1)));
			return new Match("quest_complete", f);
		}
		if ((m = DIARY_COMPLETE.matcher(line)).matches())
		{
			JsonObject f = new JsonObject();
			f.addProperty("tier", m.group(1));
			f.addProperty("area", name(m.group(2)));
			return new Match("diary_complete", f);
		}
		if (SUPERIOR.matcher(line).matches())
		{
			return new Match("superior_spawn", new JsonObject());
		}
		if (OWN_DEATH.matcher(line).matches())
		{
			return new Match("own_death", new JsonObject());
		}
		return null;
	}

	private static Match pet(String how)
	{
		JsonObject f = new JsonObject();
		f.addProperty("how", how);
		return new Match("pet", f);
	}

	private static String name(String value)
	{
		String trimmed = value.trim();
		return trimmed.length() > MAX_NAME ? trimmed.substring(0, MAX_NAME) : trimmed;
	}

	private static long number(String value)
	{
		try
		{
			return Long.parseLong(value.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** Seconds, or -1 if not a duration. */
	static double duration(String value)
	{
		String[] parts = value.split(":");
		if (parts.length > 3)
		{
			return -1;
		}
		double total = 0;
		try
		{
			for (String part : parts)
			{
				if (part.isEmpty()) { return -1; }
				total = total * 60 + Double.parseDouble(part);
			}
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
		return Math.round(total * 100) / 100.0;
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.io.BufferedOutputStream;
import java.io.ByteArrayOutputStream;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executor;
import java.util.function.Supplier;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;
import java.util.zip.ZipException;
import net.runelite.client.util.Filepath;
import net.runelite.client.util.LinkBrowser;

public final class MccrFileRecorder implements Recorder
{
	public static final String STUDIO_URL = "https://embertide.gg/studio/";
	// The desktop's 128 MiB archive also includes ingest checkpoints and links.
	static final int MAX_BYTES = 120 * 1024 * 1024;
	static final int END_RESERVE = 16 * 1024;
	// The desktop importer accepts 120,000 records plus a header.
	static final int MAX_RECORDS = 120_000;
	// Rows reach the partial file about once a second, so a crash leaves a readable prefix.
	static final long FLUSH_NANOS = 1_000_000_000L;
	private final Gson gson;
	private final Filepath directory;
	private final Supplier<String> stem;
	private final Executor worker;
	private final int capacity;
	private final String unique = UUID.randomUUID().toString();
	// Rows not yet in the partial file: about a second's worth.
	private final List<byte[]> pending = new ArrayList<>();
	private int count;
	private Filepath sealed;
	private String name = "";
	private State state = State.IDLE;
	private String error = "";
	private int bytes;
	private boolean full;
	private CompletableFuture<Void> saving;
	private final Object io = new Object();
	private Filepath partial;
	private GZIPOutputStream out;
	private int written;
	private boolean finished;
	private boolean draining;
	private long drainedAt = System.nanoTime() - FLUSH_NANOS;
	// osrs.motion x and y as thousandths of a tile, each actor's first absolute and then its change.
	static final String MOTION_XY = "delta-milli";
	private final Map<String, long[]> lastXY = new HashMap<>();
	private boolean compact;

	public MccrFileRecorder(Gson gson, Filepath directory, Supplier<String> stem, Executor worker)
	{
		this(gson, directory, stem, worker, MAX_BYTES);
	}

	MccrFileRecorder(Gson gson, Filepath directory, Supplier<String> stem, Executor worker, int capacity)
	{
		this.gson = gson;
		this.directory = directory;
		this.stem = stem;
		this.worker = worker;
		this.capacity = capacity;
	}

	@Override
	public synchronized State state() { return state; }

	@Override
	public synchronized String error() { return error; }

	@Override
	public synchronized String captureId() { return name.isEmpty() ? unique : name; }

	public synchronized Filepath path() { return sealed; }

	@Override
	public synchronized String destination()
	{
		return sealed == null ? "" : "Will be saved as " + sealed;
	}

	@Override
	public synchronized boolean full() { return full; }

	@Override
	public synchronized CompletableFuture<Void> open(JsonObject header)
	{
		if (state != State.IDLE)
		{
			return CompletableFuture.failedFuture(new IllegalStateException("Recording already opened."));
		}
		// The supplier may read the local player's name: this stays on the client thread.
		name = stem.get() + "-" + unique;
		sealed = directory.joinSegment(name + ".embertide");
		state = State.READY;
		if (header.has("osrs") && header.get("osrs").isJsonObject())
		{
			header = header.deepCopy();
			header.getAsJsonObject("osrs").addProperty("motion_xy", MOTION_XY);
			compact = true;
		}
		if (!enqueue(header, false))
		{
			state = State.FAILED;
			error = "The recording header exceeds the size budget.";
			return CompletableFuture.failedFuture(new IOException(error));
		}
		return CompletableFuture.completedFuture(null);
	}

	@Override
	public synchronized boolean enqueue(JsonObject record, boolean control)
	{
		if (state != State.READY || (full && !control))
		{
			return false;
		}
		byte[] row = (gson.toJson(record) + '\n').getBytes(StandardCharsets.UTF_8);
		// The budget counts rows as readers expand them, so the desktop's limit still holds.
		int plain = row.length;
		Map<String, long[]> moved = compact ? new HashMap<>() : null;
		JsonObject compacted = moved == null ? null : compactMotion(record, moved);
		if (compacted != null)
		{
			row = (gson.toJson(compacted) + '\n').getBytes(StandardCharsets.UTF_8);
		}
		if (bytes + plain > capacity - (control ? 0 : END_RESERVE)
			|| count >= MAX_RECORDS + (control ? 1 : 0))
		{
			full = true;
			return false;
		}
		pending.add(row);
		count++;
		bytes += plain;
		if (compacted != null)
		{
			lastXY.putAll(moved);
		}
		if (!draining && System.nanoTime() - drainedAt >= FLUSH_NANOS)
		{
			draining = true;
			drainedAt = System.nanoTime();
			try
			{
				worker.execute(this::drain);
			}
			catch (RuntimeException e)
			{
				draining = false;
			}
		}
		return true;
	}

	/** A copy of an osrs.motion row with x and y as thousandths, or null for any other row. */
	private JsonObject compactMotion(JsonObject record, Map<String, long[]> moved)
	{
		JsonElement type = record.get("type");
		JsonElement payload = record.get("payload");
		if (type == null || !"osrs.motion".equals(type.getAsString()) || payload == null || !payload.isJsonObject()
			|| !payload.getAsJsonObject().has("samples") || !payload.getAsJsonObject().get("samples").isJsonArray())
		{
			return null;
		}
		JsonObject copy = record.deepCopy();
		for (JsonElement element : copy.getAsJsonObject("payload").getAsJsonArray("samples"))
		{
			JsonArray sample = element.isJsonArray() ? element.getAsJsonArray() : null;
			if (sample == null || sample.size() < 3 || !isString(sample.get(0)) || !isNumber(sample.get(1)) || !isNumber(sample.get(2)))
			{
				continue;
			}
			String id = sample.get(0).getAsString();
			long x = Math.round(sample.get(1).getAsDouble() * 1000.0);
			long y = Math.round(sample.get(2).getAsDouble() * 1000.0);
			long[] seen = moved.containsKey(id) ? moved.get(id) : lastXY.get(id);
			sample.set(1, new JsonPrimitive(seen == null ? x : x - seen[0]));
			sample.set(2, new JsonPrimitive(seen == null ? y : y - seen[1]));
			moved.put(id, new long[]{x, y});
		}
		return copy;
	}

	private static boolean isString(JsonElement e) { return e.isJsonPrimitive() && e.getAsJsonPrimitive().isString(); }

	private static boolean isNumber(JsonElement e) { return e.isJsonPrimitive() && e.getAsJsonPrimitive().isNumber(); }

	private void drain()
	{
		try
		{
			synchronized (io)
			{
				if (state() == State.READY)
				{
					writePending();
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// The next drain or the save rebuilds the partial file from its readable rows.
			closeStream();
		}
		finally
		{
			synchronized (this)
			{
				draining = false;
			}
		}
	}

	/** Appends the rows not yet on disk and sync-flushes them. Called holding io. */
	private void writePending() throws IOException
	{
		if (out == null)
		{
			Filepath broken = partial;
			int kept = written;
			openPartial();
			if (broken != null)
			{
				try
				{
					copyRows(broken);
				}
				catch (IOException | RuntimeException e)
				{
					closeStream();
					partial.deleteIfExists();
					partial = broken;
					written = kept;
					throw e;
				}
			}
		}
		List<byte[]> rows;
		synchronized (this)
		{
			rows = new ArrayList<>(pending);
		}
		for (byte[] row : rows)
		{
			out.write(row);
		}
		out.flush();
		written += rows.size();
		synchronized (this)
		{
			pending.subList(0, rows.size()).clear();
		}
	}

	private void openPartial() throws IOException
	{
		directory.createDirectories();
		Filepath fresh = directory.joinSegment(name + "-" + UUID.randomUUID() + ".embertide.partial");
		out = new GZIPOutputStream(new BufferedOutputStream(
			fresh.openOutputStream(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE), 64 * 1024), 64 * 1024, true);
		partial = fresh;
	}

	/** Copies the rows already flushed to a broken partial file into the new one, then deletes it. */
	private void copyRows(Filepath broken) throws IOException
	{
		int want = written;
		written = 0;
		ByteArrayOutputStream line = new ByteArrayOutputStream();
		byte[] buffer = new byte[64 * 1024];
		try (InputStream in = new GZIPInputStream(broken.openInputStream(), 64 * 1024))
		{
			int read;
			while (written < want && (read = in.read(buffer)) > 0)
			{
				int from = 0;
				for (int i = 0; i < read && written < want; i++)
				{
					if (buffer[i] == '\n')
					{
						line.write(buffer, from, i + 1 - from);
						line.writeTo(out);
						line.reset();
						written++;
						from = i + 1;
					}
				}
				if (written < want)
				{
					line.write(buffer, from, read - from);
				}
			}
		}
		catch (EOFException | ZipException cutOff)
		{
			// Keep every whole row before the damage.
		}
		broken.deleteIfExists();
	}

	private void closeStream()
	{
		if (out != null)
		{
			try { out.close(); }
			catch (IOException ignored) { }
			out = null;
		}
	}

	@Override
	public CompletableFuture<Void> flush() { return CompletableFuture.completedFuture(null); }

	@Override
	public synchronized CompletableFuture<Void> finish()
	{
		if (state == State.COMPLETE || state == State.IDLE)
		{
			return CompletableFuture.completedFuture(null);
		}
		if (state == State.FINISHING)
		{
			return saving;
		}
		state = State.FINISHING;
		error = "";
		saving = new CompletableFuture<>();
		try
		{
			worker.execute(this::write);
		}
		catch (RuntimeException e)
		{
			failed(e);
		}
		return saving;
	}

	private void write()
	{
		synchronized (io)
		{
			try
			{
				if (!finished)
				{
					writePending();
					// The gzip trailer: a finished part is a whole gzip file.
					out.finish();
					out.close();
					out = null;
					finished = true;
				}
				// Same-directory rename without REPLACE_EXISTING. ATOMIC_MOVE can silently
				// replace its destination on some platforms, so do not request that option.
				partial.moveTo(sealed);
				partial = null;
				finished = false;
				written = 0;
				synchronized (this)
				{
					state = State.COMPLETE;
				}
				saving.complete(null);
			}
			catch (IOException | RuntimeException e)
			{
				closeStream();
				failed(e);
			}
		}
	}

	private synchronized void failed(Exception e)
	{
		state = State.FAILED;
		error = "Could not save the recording: " + e.getMessage();
		saving.completeExceptionally(e);
	}

	public void discard()
	{
		synchronized (io)
		{
			synchronized (this)
			{
				if (state != State.FAILED)
				{
					throw new IllegalStateException("Only a failed save can be discarded.");
				}
				pending.clear();
				state = State.COMPLETE;
			}
			closeStream();
			if (partial != null)
			{
				try { partial.deleteIfExists(); }
				catch (IOException | RuntimeException ignored) { }
				partial = null;
			}
			finished = false;
			written = 0;
		}
	}

	@Override
	public CompletableFuture<Void> openStudio()
	{
		if (state() != State.COMPLETE)
		{
			return CompletableFuture.failedFuture(new IOException("Save the recording before opening Studio."));
		}
		javax.swing.SwingUtilities.invokeLater(() -> LinkBrowser.browse(STUDIO_URL));
		return CompletableFuture.completedFuture(null);
	}
}

package com.extrinsiccognition.embertide;

import com.google.gson.JsonArray;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.UUID;

public final class MccrSession
{
	public static final String FORMAT = "mccr/0.1";
	public static final String PROFILE = "ec.mccr.spatial/1";
	public static final String SOURCE = "osrs.runelite";
	public static final String RECORDER = "embertide-runelite/0.2.1";
	public static final String GAME = "osrs";

	public final String id;
	public Instant capturedAt;
	/** Current coordinate space; the file header retains the initial dimension. */
	public String dimension;
	private long startedNanos;
	private final double maxSeconds;
	private int serial;
	private double lastRecordTime;

	public MccrSession(String dimension, double maxSeconds)
	{
		this(dimension, maxSeconds, Instant.now(), System.nanoTime());
	}

	MccrSession(String dimension, double maxSeconds, Instant capturedAt, long startedNanos)
	{
		this.id = "osrs-" + UUID.randomUUID();
		this.dimension = dimension;
		this.maxSeconds = maxSeconds;
		this.capturedAt = capturedAt;
		this.startedNanos = startedNanos;
	}

	public void rebase()
	{
		rebase(Instant.now(), System.nanoTime());
	}

	void rebase(Instant capturedAt, long startedNanos)
	{
		this.capturedAt = capturedAt;
		this.startedNanos = startedNanos;
	}

	public double time()
	{
		return time(System.nanoTime());
	}

	double time(long nowNanos)
	{
		double seconds = (nowNanos - startedNanos) / 1_000_000_000.0;
		seconds = Math.max(0, Math.min(maxSeconds, seconds));
		return Math.round(seconds * 10000.0) / 10000.0;
	}

	public JsonObject record(String type, double t, JsonObject payload, String user)
	{
		// Registering a newly observed event actor can emit rows inside a callback
		// that already sampled its time. Keep file order monotonic for the importer.
		t = Math.max(lastRecordTime, Math.max(0, Math.min(maxSeconds, t)));
		lastRecordTime = t;
		JsonObject row = new JsonObject();
		row.addProperty("id", id + ":r" + (++serial));
		row.addProperty("ts", capturedAt.plusNanos((long) (t * 1_000_000_000L)).toString());
		row.addProperty("elapsed_s", t);
		row.addProperty("source", SOURCE);
		row.addProperty("confidence", 1);
		row.addProperty("session_id", id + "/" + user);
		row.addProperty("user_id", user);
		row.add("character_id", JsonNull.INSTANCE);
		JsonObject salience = new JsonObject();
		salience.addProperty("rule_score", 0);
		salience.addProperty("first_time", false);
		salience.addProperty("danger", 0);
		row.add("salience_hints", salience);
		row.add("coverage", JsonNull.INSTANCE);
		row.addProperty("type", type);
		row.add("payload", payload);
		if (type.equals("world.event"))
		{
			row.add("caused_by", new JsonArray());
		}
		return row;
	}

	public int serial()
	{
		return serial;
	}
}

